DataGeneratorMasterdata = {
    init: async function (app, container) {
        await DataGeneratorMasterdata.initFromDMS("DMS/data/masterdata/received/clexdemocompanies-all.xml", "");
    },

    initFromDMS: async function (masterdataDMSPath, transactionDMSPath, container) {
        var masterdataFile = "";
        try {
            $("[name=masterdataTitle]", container).html($("[name=masterdataTitle]", container).html() + " at " + masterdataDMSPath);
            masterdataFile = await api.get(masterdataDMSPath);
        } catch(err) {
            $("[name=masterdataTitle]", container).html($("[name=masterdataTitle]", container).html() + " template");
            masterdataFile = "<?xml version='1.0' encoding='UTF-8'?><Companies SourceSystem=\"Demo\"></Companies>";
        }
        var masterdataJson = await DataGeneratorMasterdata.buildMasterdataJSON(masterdataFile);
       await DataGeneratorMasterdata.setupMasterdataGrid($("[name=masterdataGrid]", container), { data: masterdataJson });

    },

    buildMasterdataJSON: async function (masterdataXmlString) {
        var parser = new DOMParser(),
            xmlDoc = parser.parseFromString(masterdataXmlString, "text/xml"),
            documentElement = xmlDoc.documentElement;
        var companies = [];
        for (var i = 0; i < documentElement.childNodes.length; i = i + 1) {
            var currentNode = documentElement.childNodes[i];
            if (currentNode.nodeName == "Company") {
                var companyDef = {};
                companyDef.Name = currentNode.getAttribute("Name");
                for (var j = 0; j < documentElement.childNodes[i].childNodes.length; j++) {
                    var currentNode = documentElement.childNodes[i].childNodes[j];
                    if (currentNode.nodeName == "Address") {
                        companyDef.Address = {};
                        companyDef.Address.CountryCode = currentNode.getAttribute("CountryCode");
                        var addressDetails = currentNode.childNodes;
                        for (var k = 0; k < addressDetails.length; k = i + 1) {
                            if (addressDetails[k].nodeName.indexOf("#") === -1) {
                                companyDef.Address[addressDetails[k].nodeName] = addressDetails[k].childNodes[0].nodeValue;
                            }
                        }
                    } else if (currentNode.nodeName == "References") {
                        companyDef.References = [];
                        for (var k = 0; k < currentNode.childNodes.length; k++) {
                            if (currentNode.childNodes[k].nodeName.indexOf("#") === -1) {
                                companyDef.References.push({
                                    System: currentNode.childNodes[k].getAttribute("System"),
                                    Value: currentNode.childNodes[k].getAttribute("Value")
                                });
                            }
                        }
                    }
                }
                companies.push(companyDef);
            }
        }
        return companies;
    },

    buildMasterdataXml: async function(jsonArray) {
        var result = "<Companies>";
        for (var i = 0; i < jsonArray.length; i = i + 1) {
            var currentCompany = jsonArray[i];
            result += "\n<Company Name=\"" + currentCompany.Name + "\">";
            result += "\n<Address ";
            if (currentCompany.Address.CountryCode) {
                result += "CountryCode=\"" + currentCompany.Address.CountryCode + "\"";
            }
            result += ">";
            for (var key in currentCompany.Address) {
                if (currentCompany.Address.hasOwnProperty(key) && currentCompany.Address[key].length > 0 && key !== "CountryCode") {
                    result += "\n<" + key + ">" + currentCompany.Address[key] + "</" + key + ">";
                }
            }
            result += "\n</Address>";
            result += "\n<References>";
            for(var j = 0; j < currentCompany.References.length; j = j + 1) {
                var currentReference = currentCompany.References[j];
                result += "\n<Reference System=\"" + currentReference.System + "\" Value=\"" + currentReference.Value + "\"></Reference>";
            }
            result += "\n</References>";
            result += "\n</Company>";
        }
        result += "\n</Companies>";
        return result;
    },

    viewMasterdataXml: async function(grid) {
        var d = new Dialog({
            title: "[resource_displayname[viewmasterdataxml]]",
            width: 800,
            height: 600
        });
        d.template = "<div name='masterdataXml' style='width:700px;height:500px;'></div>";
        d.init(async () => {
            var gridData = JSON.parse(JSON.stringify(grid.kendoObject.dataSource.data()));
            var xmlCode = await DataGeneratorMasterdata.buildMasterdataXml(gridData);
            var editor = new MonacoEditor($("[name=masterdataXml]")[0], {
                code: xmlCode,
                language: "xml",
                automaticLayout: true
            });
            editor.init();
        });
    },

    setupMasterdataGrid: async function (gridContainer, data) {
        data = new kendo.data.DataSource(data);
        var d = new GridWidget(gridContainer, data);
        d.detailTemplate = $("[name=companyProposalDetails]").html();
        d.detailExpand = async function (e) {
            await DataGeneratorMasterdata.expandMasterdata(e, d);
        };
        d.toolbar = "<button name='viewRaw'>[resource_displayname[viewrawxml]]</button> <button name='addCompany'>[resource_displayname[addcompany]]</button>";
        d.groupable = false;
        d.editable = {
            confirmation: false
        };
        d.columns = [{ field: "Name" }];
        d.commands.push({
            icon: "k-i-delete",
            name: "delete",
            text: "[resource_displayname[delete]]"
        });
        d.dataBound = function (e) {
            $("[name=delete]", d.gridElement).off("click").on("click", function (e) {
                DataGeneratorMasterdata.removeMasterdataCompany(e, d);
            });
        };
        d.init(() => {
            $("[name=viewRaw]", d.gridElement).off("click").on("click", function(e) {
                DataGeneratorMasterdata.viewMasterdataXml(d);
            });
            $("[name=addCompany]", d.gridElement).off("click").on("click", function(e) {
                DataGeneratorMasterdata.addMasterdataCompany(d);
            });
        });
    },

    removeMasterdataCompany(e, grid) {
        e.preventDefault();
        var row = $(e.currentTarget).closest("tr");
        grid.kendoObject.removeRow(row);
    },

    addMasterdataCompany(grid) {
        var d = new Dialog({
            title: "[resource_displayname[addcompany]]"
        });
        d.template = $("[name=addCompanyDialog]").html();
        d.events.create = function (e) {
            d.events.close();
            var name = $("[name=name]", d.element).val();
            grid.kendoObject.dataSource.add({
                Name: name,
                References: [],
                Address: {}
            });
        };
        d.init();
    },

    expandMasterdata: async function (e, grid) {
        var masterdataEntry = grid.kendoObject.dataItem(e.masterRow),
            container = $(e.detailRow);
        var requiredFields = ["Line1", "Line2", "ZipOrPostalCode", "TownOrCity", "Region", "CountryCode"];
        for (var i = 0; i < requiredFields.length; i = i + 1) {
            if (!masterdataEntry.Address[requiredFields[i]]) { masterdataEntry.Address[requiredFields[i]] = ""; }
        }
        var kendoAddress = new kendo.observable(masterdataEntry.Address);
        kendo.bind($("[name=address]", container), kendoAddress);
        container.data("model", kendoAddress);
        kendoAddress.bind("change", function () { masterdataEntry.Address = JSON.parse(JSON.stringify(kendoAddress)) });
        await DataGeneratorMasterdata.setupMasterdataReferences($("[name=referencesGrid]", container), masterdataEntry.References);
    },

    addMasterdataReference(grid) {
        var d = new Dialog({
            title: "[resource_displayname[addreference]]"
        });
        d.template = $("[name=addReferenceDialog]").html();
        d.events.create = function (e) {
            d.events.close();
            var system = $("[name=system]", d.element).val(),
                value = $("[name=value]", d.element).val();
            grid.kendoObject.dataSource.add({
                System: system,
                Value: value
            });
        };
        d.init();
    },

    removeMasterdataReference(e, grid) {
        e.preventDefault();
        var row = $(e.currentTarget).closest("tr");
        grid.kendoObject.removeRow(row);
    },

    setupMasterdataReferences: async function (gridContainer, data) {
        data = new kendo.data.DataSource({
            "data": data,
            "change": function (e) {
                var gridData = this.data();
                data = JSON.parse(JSON.stringify(gridData));
            }
        });
        var d = new GridWidget(gridContainer, data);
        d.columns = [{ field: "System" }, { field: "Value" }];
        d.groupable = false;
        d.editable = {
            confirmation: false
        };
        d.commands.push({
            name: "delete",
            text: "[resource_displayname[delete]]",
            icon: "k-i-delete"
        });
        d.toolbar = "<button name='addReference'>[resource_displayname[AddReference]]</button>";
        d.dataBound = function (e) {
            $("a[name=delete]", d.gridElement).off("click").on("click", function (ev) {
                DataGeneratorMasterdata.removeMasterdataReference(ev, d);
            });
        };
        d.init(() => {
            $("button[name=addReference]").off("click").on("click", function (e) {
                DataGeneratorMasterdata.addMasterdataReference(d);
            });
        });
    }
}
